const asset = n => `assets/art-${String(n).padStart(2,'0')}.webp`;
const artists = [
{id:'anna-molka-ahmed',name:'Anna Molka Ahmed',years:'1917–1994',field:'Painting & education',category:'Painting',portrait:asset(4),art:[1,5,3,2],line:'She made room for the artists who came after.',intro:'A painter and educator whose contribution reaches beyond the canvas, into the classrooms where generations of artists began.',story:'Anna Molka Ahmed helped establish fine arts education in Lahore. In 1940, she founded the Fine Arts Department at the University of the Punjab, now its College of Art & Design.',practice:'Her painting brings together portraiture, landscape, and scenes of everyday life. The supplied collection offers a glimpse of her expressive use of colour and paint.',legacy:'Her decades of teaching helped build an enduring foundation for art education in Pakistan. Remembering her means remembering the institutions and opportunities women helped create.',source:'https://pu.edu.pk/home/section/allpress/10687',sourceName:'University of the Punjab · Anna Molka Ahmed',milestone:'1940',event:'Establishes the Fine Arts Department at the University of the Punjab.'},
{id:'zubeida-agha',name:'Zubeida Agha',years:'1922–1997',field:'Modernism & abstraction',category:'Modernism',portrait:'assets/zubeida-portrait.webp',art:[19,17,16,18],line:'A new nation. A different way of seeing.',intro:'A pioneering modernist whose language of colour and form opened new possibilities for painting in Pakistan.',story:'Zubeida Agha holds a defining place in Pakistan’s modern art history. Trained in Pakistan and Europe, she developed an approach that moved beyond the expectations of representational painting.',practice:'Her work explored colour, space, and abstraction. La Biennale di Venezia describes her later geometric work as part of a counternarrative built by women artists in the post-war decades.',legacy:'Her place in modernism challenges a history told through men alone. Her work asks us to see experimentation and cultural change as part of women’s contributions to Pakistan.',source:'https://www.labiennale.org/en/art/2024/abstraction/zubeida-agha',sourceName:'La Biennale di Venezia · Zubeida Agha',extraSource:'https://www.metmuseum.org/ko/essays/modern-art-in-west-and-east-pakistan',extraName:'The Metropolitan Museum of Art · Modern Art in West and East Pakistan',milestone:'1949',event:'Her early modernist exhibition challenges established expectations of painting.'},
{id:'laila-shahzada',name:'Laila Shahzada',years:'1926–1994',field:'Painting & cultural memory',category:'Painting',portrait:asset(7),art:[9,10,8,6],line:'She found whole worlds in the shapes left behind.',intro:'A painter who turned driftwood, landscape, and the memory of ancient civilisations into a deeply personal visual language.',story:'Laila Shahzada developed a distinctive practice in Pakistan, moving between observed forms and expressive abstraction. Her work drew on both the natural world and the region’s cultural past.',practice:'Her Drift Moods series, exhibited in 1964, grew from the weathered shapes of driftwood. Later, the artefacts of the Indus Valley Civilisation inspired her Moenjodaro series.',legacy:'Her paintings helped bring Pakistan’s ancient visual heritage into modern art. She connected the intimate act of looking with a much longer history of place.',source:'https://lailashahzada.com/recognition/ten-great-artists-stamps-pakistan.html',sourceName:'Laila Shahzada archive · Pakistan Post tribute',milestone:'1964',event:'The Drift Moods series brings the forms of weathered driftwood into painting.'},
{id:'salima-hashmi',name:'Salima Hashmi',years:'Born 1942',field:'Painting, teaching & curation',category:'Education',portrait:asset(28),art:[27,25,30,29],line:'An artist’s voice can carry other voices, too.',intro:'An artist, educator, curator, and writer who has helped make space for art—and for the histories of women who create it.',story:'Salima Hashmi’s contribution spans artistic practice, teaching, writing, and exhibition-making. She taught at the National College of Arts and served as its principal, before becoming founding dean of BNU’s visual arts and design school.',practice:'Her work across painting, curation, and writing brings artistic expression into conversation with social experience. She has also supported younger artists through gallery spaces and education.',legacy:'Her book Unveiling the Visible: Lives and Works of Women Artists of Pakistan makes women’s creative contributions part of the written record. Her legacy includes both her own work and the platforms she helped build.',source:'https://bnu.edu.pk/faculty/professor-salima-hashmi',sourceName:'Beaconhouse National University · Salima Hashmi',milestone:'2002',event:'Publishes Unveiling the Visible: Lives and Works of Women Artists of Pakistan.'},
{id:'shahzia-sikander',name:'Shahzia Sikander',years:'Born 1969',field:'Miniature & contemporary art',category:'Contemporary',portrait:asset(23),art:[20,21,22,24],line:'Tradition was a beginning, never a boundary.',intro:'An artist who reimagined miniature painting as a language for contemporary experience, identity, and change.',story:'Born in Lahore, Shahzia Sikander trained in miniature painting at the National College of Arts, earning her BFA in 1991. She studied with master miniaturist Bashir Ahmad.',practice:'Her breakthrough work The Scroll (1989–90) challenged the technical and aesthetic conventions of the medium. Her practice helped bring miniature painting into international contemporary art conversations.',legacy:'Her work expands what inherited forms can say and who can speak through them. She also became the first woman to teach in NCA’s Miniature Painting Department.',source:'https://www.shahziasikander.com/biography',sourceName:'Shahzia Sikander · Official biography',milestone:'1989–90',event:'Creates The Scroll, a breakthrough in her rethinking of miniature painting.'},
{id:'nahid-raza',name:'Nahid Raza',years:'Born 1948',field:'Painting & symbolism',category:'Contemporary',portrait:asset(15),art:[13,11,12,14],line:'Memory, repetition, and a language of her own.',intro:'A painter and teacher whose evolving practice moves through cultural memory, repeated motifs, and spiritual reflection.',story:'Nahid Raza began studying art at Karachi’s Central Institute in 1966. Her early major work drew inspiration from the intricate stone carvings of Sindh’s Chawkandi tombs.',practice:'Her practice has continued to evolve. In the Virdh series presented at Karachi Biennale 2017, repeated motifs reflect on incantation, devotion, and inner experience.',legacy:'Alongside exhibiting, she taught and founded Studio Art in Karachi in 1992, nurturing emerging artists. Her story belongs to the history of women sustaining artistic communities as well as making art.',source:'https://www.kbcuratorial.com/artists/nahid-raza',sourceName:'Karachi Biennale 2017 · Nahid Raza',milestone:'1992',event:'Establishes Studio Art in Karachi, supporting a new generation of artists.'}
];
const works = artists.flatMap(a=>a.art.map((n,i)=>({src:asset(n),artist:a,id:`${a.id}-${i}`,label:`Collection image ${String(i+1).padStart(2,'0')}`})));
